import redis

r = redis.Redis(decode_responses=True)
BOARD = "lb:2026-W48"                      # one sorted set per board and period

# Atomic: mark the match as applied and add its points; a redelivery does nothing
APPLY = r.register_script("""
if redis.call('SET', KEYS[2], 1, 'NX', 'EX', 604800) then
  return redis.call('ZINCRBY', KEYS[1], ARGV[1], ARGV[2])
end""")

def record_match(match_id: str, player: str, points: int) -> None:
    APPLY(keys=[BOARD, f"applied:{match_id}:{player}"], args=[points, player])  # O(log N)

def top(n: int = 10):
    return r.zrange(BOARD, 0, n - 1, desc=True, withscores=True)   # O(log N + n)

def around_me(player: str, span: int = 5):
    rank = r.zrevrank(BOARD, player)       # 0-based, O(log N); None if unranked
    if rank is None:
        return None, []
    rows = r.zrange(BOARD, max(0, rank - span), rank + span, desc=True, withscores=True)
    return rank + 1, rows                  # 1-based rank plus neighbours

def rebuild(scores_db) -> None:
    """Redis lost the board: reload it from the source of truth, then swap."""
    tmp = BOARD + ":rebuild"
    r.delete(tmp)
    for batch in scores_db.iter_scores(batch_size=10_000):   # [(player, score), ...]
        r.zadd(tmp, dict(batch))
    r.rename(tmp, BOARD)                   # atomic switch; then replay newer matches
